('INM', 'inmobiliario.ficha_inmuebles', 'Ficha de Inmuebles',
 'Extrae ficha inmueble: ubicacion, superficie, uso, datos registrales, cargas, hipotecas, servidumbres',
 'extraccion',
 E'Analiza la documentacion inmobiliaria de [sociedad_target]. Para cada inmueble extrae:\\n\\n1. ubicacion: direccion, municipio, provincia, referencia catastral\\n2. superficie: construida, util, parcela\\n3. uso: oficinas, industrial, comercial, residencial, mixto\\n4. titulo: escritura de adquisicion, fecha, notario, protocolo\\n5. datos_registrales: registro propiedad, tomo, libro, folio, finca\\n6. cargas: hipotecas (importe, acreedor, vencimiento), embargos, anotaciones preventivas\\n7. servidumbres: tipo, beneficiario\\n8. situacion_urbanistica: clasificacion suelo, calificacion, afecciones\\n9. valor: valor de adquisicion, valor catastral, ultima tasacion si consta\\n10. estado_ocupacional: propiedad libre, arrendado, ocupado\\n\\nDestaca cargas no canceladas e inmuebles sin inscripcion registral actualizada.',
 '{"type":"object","properties":{"inmuebles":{"type":"array","items":{"type":"object","properties":{"ubicacion":{"type":"string"},"ref_catastral":{"type":"string"},"superficie":{"type":"object","properties":{"construida":{"type":"number"},"util":{"type":"number"},"unidad":{"type":"string"}}},"uso":{"type":"string"},"datos_registrales":{"type":"object","properties":{"registro":{"type":"string"},"finca":{"type":"string"},"tomo":{"type":"string"}}},"cargas":{"type":"array","items":{"type":"object","properties":{"tipo":{"type":"string"},"acreedor":{"type":"string"},"importe":{"type":"number"},"estado":{"type":"string"}}}},"servidumbres":{"type":"array","items":{"type":"string"}},"valor_adquisicion":{"type":"number"},"estado_ocupacional":{"type":"string"},"red_flags":{"type":"array","items":{"type":"string"}}}}},"evidencias":{"type":"array","items":{"type":"object","properties":{"doc_id":{"type":"string"},"pagina":{"type":"string"}}}}}}',
 '[{"type":"document","source":"nota_simple","required":true},{"type":"registry_scrape","source":"catastro","required":false}]',
 '{"paranoico","validador","sanitizer"}'),

('INM', 'inmobiliario.arrendamientos', 'Ficha Arrendamientos',
 'Extrae terminos arrendamiento: ubicacion, arrendador/arrendatario, renta, duracion, renovacion, CoC, actualizacion',
 'extraccion',
 E'Analiza los contratos de arrendamiento de [sociedad_target]. Para cada contrato extrae:\\n\\n1. ubicacion: inmueble arrendado\\n2. partes: arrendador, arrendatario\\n3. renta: importe mensual/anual, moneda\\n4. actualizacion: mecanismo (IPC, fijo, mercado), frecuencia\\n5. duracion: inicio, fin, prorroga obligatoria/voluntaria\\n6. fianza_garantias: meses fianza, aval bancario, deposito\\n7. cambio_control: clausula CoC, consentimiento arrendador\\n8. subarriendo: permitido/prohibido, condiciones\\n9. obras: clausulas de obras, estado devolucion\\n10. resolucion: causas de terminacion anticipada, indemnizacion\\n\\nIdentifica arrendamientos con renta por encima de mercado, vencimientos proximos sin renovacion, y clausulas CoC bloqueantes.',
 '{"type":"object","properties":{"arrendamientos":{"type":"array","items":{"type":"object","properties":{"ubicacion":{"type":"string"},"arrendador":{"type":"string"},"renta_anual":{"type":"number"},"actualizacion":{"type":"string"},"duracion":{"type":"object","properties":{"inicio":{"type":"string"},"fin":{"type":"string"},"prorroga":{"type":"string"}}},"cambio_control":{"type":"object","properties":{"existe":{"type":"boolean"},"condiciones":{"type":"string"}}},"red_flags":{"type":"array","items":{"type":"string"}}}}},"renta_total_anual":{"type":"number"},"evidencias":{"type":"array","items":{"type":"object","properties":{"doc_id":{"type":"string"},"clausula":{"type":"string"}}}}}}',
 '[{"type":"document","source":"contratos_arrendamiento","required":true}]',
