('ADMIN', 'regulatorio.licencias_autorizaciones', 'Inventario Licencias y Autorizaciones',
 'Extrae inventario licencias: tipo, autoridad, fecha, vigencia, condiciones renovacion, requisitos sectoriales',
 'extraccion',
 E'Extrae el inventario completo de licencias, autorizaciones y registros obligatorios de [sociedad_target] (sector: [sector]):\\n\\n1. tipo: licencia actividad, autorizacion administrativa, inscripcion registro obligatorio, homologacion\\n2. autoridad_otorgante: organismo (estatal, autonomico, local)\\n3. fecha_otorgamiento\\n4. vigencia: plazo, caducidad, renovacion\\n5. condiciones: requisitos de mantenimiento, informes periodicos\\n6. estado: vigente, caducada, en renovacion, revocada\\n7. requisitos_sectoriales: especificos del sector [sector]\\n\\nIdentifica licencias caducadas o proximas a caducidad, actividades ejercidas sin licencia, y requisitos regulatorios no cumplidos.',
 '{"type":"object","properties":{"licencias":{"type":"array","items":{"type":"object","properties":{"tipo":{"type":"string"},"autoridad":{"type":"string"},"fecha":{"type":"string"},"vigencia":{"type":"string"},"estado":{"type":"string"},"condiciones":{"type":"array","items":{"type":"string"}},"red_flags":{"type":"array","items":{"type":"string"}}}}},"gaps_regulatorios":{"type":"array","items":{"type":"string"}},"evidencias":{"type":"array","items":{"type":"object","properties":{"doc_id":{"type":"string"},"pagina":{"type":"string"}}}}}}',
