('MA', 'medioambiental.autorizaciones_ambientales', 'Autorizaciones Ambientales',
 'Extrae autorizaciones ambientales: tipo, autoridad, fecha, vigencia, evaluaciones impacto, gestion residuos',
 'extraccion',
 E'Extrae las autorizaciones y licencias ambientales de [sociedad_target]:\\n\\n1. autorizacion_ambiental_integrada: AAI si aplica (actividades Anexo 1 Ley 16/2002)\\n2. evaluacion_impacto_ambiental: DIA, resoluciones, condiciones\\n3. autorizaciones_vertido: tipo, cuenca, parametros\\n4. gestion_residuos: autorizacion productor, gestor, NIMA, contratos gestores autorizados\\n5. emisiones: autorizacion GEI, permisos emision, huella carbono\\n6. suelos_contaminados: declaraciones de suelo contaminado, investigaciones, descontaminacion\\n7. estado: vigente, caducada, en tramite\\n8. inspecciones_ambientales: resultados ultimas inspecciones\\n\\nDestaca incumplimientos que generen riesgo de sancion o responsabilidad medioambiental.',
 '{"type":"object","properties":{"autorizaciones":{"type":"array","items":{"type":"object","properties":{"tipo":{"type":"string"},"autoridad":{"type":"string"},"fecha":{"type":"string"},"vigencia":{"type":"string"},"estado":{"type":"string"},"condiciones":{"type":"array","items":{"type":"string"}}}}},"suelos":{"type":"object","properties":{"investigacion_realizada":{"type":"boolean"},"contaminacion_detectada":{"type":"boolean"},"descripcion":{"type":"string"}}},"inspecciones":{"type":"array","items":{"type":"object","properties":{"fecha":{"type":"string"},"resultado":{"type":"string"},"requerimientos":{"type":"array","items":{"type":"string"}}}}},"red_flags":{"type":"array","items":{"type":"string"}},"evidencias":{"type":"array","items":{"type":"object","properties":{"doc_id":{"type":"string"},"pagina":{"type":"string"}}}}}}',
