('MA', 'medioambiental.contingencias_ambientales', 'Contingencias Ambientales',
 'Analiza contingencias ambientales: riesgo contaminacion, permisos caducados, sanciones, costes remediacion',
 'analisis',
 E'Analiza las contingencias medioambientales de [sociedad_target]:\\n\\n1. Contaminacion de suelos: investigaciones realizadas, resultados, obligacion de descontaminacion, coste estimado\\n2. Permisos caducados: autorizaciones ambientales no renovadas, riesgo de cese actividad\\n3. Procedimientos sancionadores: expedientes ambientales abiertos o concluidos\\n4. Responsabilidad medioambiental: garantia financiera obligatoria (Ley 26/2007), cobertura\\n5. Pasivos ambientales latentes: amianto, residuos historicos, PCBs\\n6. Costes de adaptacion: inversiones necesarias para cumplimiento normativo futuro\\n\\nCuantifica cada contingencia con provision recomendada y clasifica segun probabilidad NIC 37.',
 '{"type":"object","properties":{"contingencias":{"type":"array","items":{"type":"object","properties":{"tipo":{"type":"string"},"descripcion":{"type":"string"},"importe_estimado":{"type":"number"},"probabilidad":{"type":"string"},"provision_recomendada":{"type":"number"}}}},"riesgo_total":{"type":"object","properties":{"importe":{"type":"number"},"nivel":{"type":"string"}}},"inversiones_necesarias":{"type":"array","items":{"type":"object","properties":{"concepto":{"type":"string"},"importe":{"type":"number"},"plazo":{"type":"string"}}}},"recomendaciones_spa":{"type":"array","items":{"type":"string"}},"evidencias":{"type":"array","items":{"type":"object","properties":{"doc_id":{"type":"string"},"pagina":{"type":"string"}}}}}}',
